import{_ as s,o as t,a as l,b as n}from"./app.DKoEZOcr.js";const p="/ascendc.github.io/pr/5487/assets/datacopypad3.BvqMTyYV.png",i="/ascendc.github.io/pr/5487/assets/datacopypad4.Vq5KlQ6I.png",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"数据搬运","link":"/api/SIMD-API/basic_api/memory_vector_compute/data_move/data_move"},{"text":"DataCopyPad（UB -> GM非对齐数据搬运）","link":"/api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopyPad_UBToGM"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopyPad_UBToGM.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopyPad_UBToGM.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":3,"title":"不支持数据搬运模式mode的原型","slug":"不支持数据搬运模式mode的原型","link":"#不支持数据搬运模式mode的原型"},{"level":3,"title":"支持数据搬运模式mode的原型","slug":"支持数据搬运模式mode的原型","link":"#支持数据搬运模式mode的原型"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),e={name:"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopyPad_UBToGM.md"};function d(c,a,o,r,h,_){return t(),l("div",null,[...a[0]||(a[0]=[n(`<div><article class="markdown-body"><h1>DataCopyPad（UBToGM非对齐数据搬运）<span id="ZH-CN_TOPIC_0000001894460401"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><h3 id="不支持数据搬运模式mode的原型">不支持数据搬运模式mode的原型<a class="header-anchor" href="#不支持数据搬运模式mode的原型">​</a></h3><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h3 id="支持数据搬运模式mode的原型">支持数据搬运模式mode的原型<a class="header-anchor" href="#支持数据搬运模式mode的原型">​</a></h3><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_data_copy_intf.h&quot;</code>。</p><p>该接口提供将数据从Unified Buffer（UB）非对齐搬运至Global Memory的功能。</p><p>具体支持的数据通路为（以<a href="../../aux_data_structures/TPosition.html">逻辑位置TPosition</a>表示）：</p><ul><li><p>UB -&gt; Global Memory</p><ul><li>VECIN -&gt; GM</li><li>VECOUT -&gt; GM</li></ul></li><li><p>如<a href="#fig_datacopypad3">图1</a>所示，对于32字节对齐搬运场景，从UB读取的所有数据都会搬运至Global Memory。</p></li><li><p>如<a href="#fig_datacopypad4">图2</a>所示，对于非32字节对齐的场景，在读取UB数据时会填入dummy假数据，对齐到32B，搬入Global Memory时会将dummy空数据丢弃，从而实现UB到Global Memory的非对齐搬运。</p></li></ul><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>不支持配置设置数据搬运模式mode</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopyPad</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyExtParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dataCopyParams</span><span class="p">)</span>
</code></pre></div></li></ul><div data-filter="950"><ul><li><p>支持配置设置数据搬运模式mode（仅Ascend 950PR/Ascend 950DT支持）</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 该函数原型仅支持Ascend 950PR/Ascend 950DT</span>
<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="n">PaddingMode</span><span class="w"> </span><span class="n">mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">PaddingMode</span><span class="o">::</span><span class="n">Normal</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopyPad</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyExtParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dataCopyParams</span><span class="p">)</span>
</code></pre></div></li></ul></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">T</td><td align="left">操作数的数据类型。各产品支持的数据类型请参考<a href="#section4219135304818">数据类型</a>。</td></tr><tr><td align="left">mode</td><td align="left">配置数据搬运模式。PaddingMode类型，定义如下：<br>enum class PaddingMode : uint8_t {<br> Normal = 0, // 默认模式，与原有数据搬运格式保持一致，每次数据搬运都会补齐至32字节对齐<br> Compact, // 紧凑模式，允许单次搬运不对齐，统一在整块数据末尾补齐至32字节对齐<br>};</td></tr></tbody></table><p><strong>表2</strong> 接口参数说明</p><table><thead><tr><th align="left">参数名</th><th align="center">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">dst</td><td align="center">输出</td><td align="left">目的操作数，类型为<a href="../../data_structures/GlobalTensor/GlobalTensor_intro.html">GlobalTensor</a>。<br>起始地址无地址对齐约束。</td></tr><tr><td align="left">src</td><td align="center">输入</td><td align="left">源操作数，类型为<a href="../../data_structures/LocalTensor/LocalTensor_intro.html">LocalTensor</a>。<br>起始地址需要保证32字节对齐。</td></tr><tr><td align="left">dataCopyParams</td><td align="center">输入</td><td align="left">搬运参数，DataCopyExtParams类型，具体参数说明请参考<a href="#table_ub2gm_pad_3">表3</a>。</td></tr></tbody></table><p>下文表格中列出的结构体参数定义请参考<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_data_copy.h</code>，<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。</p><p><strong>表3</strong> DataCopyExtParams结构体参数定义<span id="table_ub2gm_pad_3"></span></p><table><thead><tr><th align="left">参数名</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">blockCount</td><td align="left">指定该指令包含的连续传输数据块个数，数据类型为uint16_t，取值范围：blockCount∈[0, 4095]。</td></tr><tr><td align="left">blockLen</td><td align="left">指定该指令每个连续传输数据块长度，<strong>该指令支持非对齐搬运</strong>，<strong>每个连续传输数据块长度单位为字节</strong>。数据类型为uint32_t，取值范围：blockLen∈[0, 2097151]<strong>，blockLen必须是sizeof(T)的整数倍，需要注意不要超过UB空间大小</strong>。</td></tr><tr><td align="left">srcStride</td><td align="left">源操作数，相邻连续数据块的间隔（即前一个数据块<strong>结束地址</strong>与后一个数据块<strong>起始地址</strong>的差值）。<br>源操作数的逻辑位置为VECIN/VECOUT，单位为dataBlock（32字节）。<br>数据类型为uint32_t，取值范围为[0, 2^32-1]。不同产品中srcStride的数据类型和支持的取值范围可能不同，详细请参考<a href="#section633mcpsimp">约束说明</a>。</td></tr><tr><td align="left">dstStride</td><td align="left">目的操作数，相邻连续数据块间的间隔（即前一个数据块<strong>结束地址</strong>与后一个数据块<strong>起始地址</strong>的差值）。<br>目的操作数的逻辑位置为GM，单位为字节。<br>数据类型为uint32_t，取值范围为[0, 2^32-1]。不同产品中dstStride的数据类型和支持的取值范围可能不同，详细请参考<a href="#section633mcpsimp">约束说明</a>。</td></tr><tr><td align="left">rsv</td><td align="left">保留字段。</td></tr></tbody></table><p>下面通过两个场景介绍UB到Global Memory的非对齐搬运，分别对应32字节对齐和非32字节对齐：</p><ul><li><p>32字节对齐场景<span id="32字节对齐场景"></span></p><p>如<a href="#fig_datacopypad3">图1</a>所示，blockLen为64，每个连续传输数据块包含64字节；srcStride为1，源操作数的逻辑位置为VECIN/VECOUT，srcStride的单位为dataBlock（32字节），即源操作数相邻数据块之间间隔1个dataBlock；dstStride为1，目的操作数的逻辑位置为GM，dstStride的单位为字节，即目的操作数相邻数据块之间间隔1字节。</p><p>对于32字节对齐搬运场景，从UB读取的所有数据都会搬运至Global Memory。</p><p><strong>图1</strong> blockLen为32字节对齐时UB到Global Memory的非对齐搬运示意图<span id="fig_datacopypad3"></span><br><img src="`+p+'" alt></p></li><li><p>非32字节对齐场景<span id="非32字节对齐场景"></span></p><p>如<a href="#fig_datacopypad4">图2</a>所示，blockLen为47，每个连续传输数据块包含47字节，不满足32字节对齐；srcStride为1，表示源操作数相邻数据块之间间隔1个dataBlock；dstStride为1，表示目的操作数相邻数据块之间间隔1字节。</p><p>对于非32字节对齐的场景，由于UB要求32字节对齐，框架在搬出时会自动补充17字节的假数据来保证对齐，搬到Global Memory时再自动将填充的假数据丢弃掉，从而实现UB到Global Memory的非对齐搬运。</p><p><strong>图2</strong> blockLen不满足32字节对齐时UB到Global Memory的非对齐搬运示意图<span id="fig_datacopypad4"></span><br><img src="'+i+`" alt></p></li></ul><h2 id="数据类型">数据类型<span id="section4219135304818"></span><a class="header-anchor" href="#数据类型">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT，支持的数据类型为：bool、int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32、int64_t、uint64_t、double、complex64。</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、uint64_t、double。</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、uint64_t、double。</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float。</li></ul></div><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>位于UB的源地址必须32字节对齐，位于Global Memory的目的地址必须1字节对齐。</p></li><li><p>DataCopyExtParams结构体参数的值需在取值范围内：</p><p><strong>表4</strong> DataCopyExtParams结构体参数取值范围</p><table><thead><tr><th>参数名</th><th>取值范围</th></tr></thead><tbody><tr><td>blockCount</td><td>[0, 4095]</td></tr><tr><td>blockLen</td><td>[0, 2097151]</td></tr><tr><td>srcStride</td><td>[0, 2^32 - 1]</td></tr><tr><td>dstStride</td><td>[0, 2^32 - 1]</td></tr></tbody></table><div data-filter="950"><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 特别地，针对Ascend 950PR/Ascend 950DT，srcStride和dstStride的数据类型和取值范围如下：</p><ul><li>srcStride：数据类型为int64_t，取值范围为[0, 65535]。</li><li>dstStride：数据类型为int64_t，取值范围为[0, 2^40-1]。</li></ul></div></div></li></ul><div data-filter="A3,910b,950"><ul><li>当DataCopyExtParams结构体参数blockCount、blockLen任意一个值为0时，该接口将被视为NOP（空操作）。该说明针对如下型号生效： <div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT</li></ul></div></li></ul></div><h2 id="调用示例">调用示例<span id="section177231425115410"></span><a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyExtParams</span><span class="w"> </span><span class="n">copyParams</span><span class="p">{</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">dstTotalLength</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">T</span><span class="p">),</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyPad</span><span class="p">(</span><span class="n">dstGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">copyParams</span><span class="p">);</span>
</code></pre></div><p>完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/00_data_movement/data_copy_pad_gm2ub_ub2gm">DataCopyPad样例</a>。</p></article></div>`,1)])])}const v=s(e,[["render",d]]);export{m as __pageData,v as default};
